 public static void BodyInputs(){Guard(()=>{foreach(int angle in new[]{0,180}){var go=Model();go.transform.rotation=Quaternion.Euler(0,angle,0);var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");r.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Original_LOD0.asset");var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);texture.LoadImage(File.ReadAllBytes(Out+"/Original_Albedo.png"));var mat=new Material(Shader.Find("Unlit/Texture"));mat.mainTexture=texture;r.sharedMaterial=mat;Render(go,"Body_Input_"+angle,0,false,true);UnityEngine.Object.DestroyImmediate(go);}});}
 public static void AtlasCandidates(){Guard(()=>{foreach(string name in new[]{"Albedo","Albedo_Feral","Normal","RMOE_Normal","RMOE_Feral","RMOE_Special"}){string path=Folder+"/Atlas_"+name+".png";if(name.StartsWith("RMOE")){var rgb=new Texture2D(2,2,TextureFormat.RGBA32,false,true);rgb.LoadImage(File.ReadAllBytes(Out+"/Atlas_"+name+".png"));var alpha=new Texture2D(2,2,TextureFormat.RGBA32,false,true);alpha.LoadImage(File.ReadAllBytes(Out+"/Alpha_"+name+".png"));var pixels=rgb.GetPixels();var ap=alpha.GetPixels();for(int i=0;i<pixels.Length;i++)pixels[i].a=ap[i].r;rgb.SetPixels(pixels);rgb.Apply();File.WriteAllBytes(path,rgb.EncodeToPNG());}else File.Copy(Out+"/Atlas_"+name+".png",path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);int size=name.StartsWith("RMOE")?512:2048;importer.maxTextureSize=size;importer.sRGBTexture=name.StartsWith("Albedo");importer.textureType=name=="Normal"?TextureImporterType.NormalMap:TextureImporterType.Default;importer.mipmapEnabled=true;importer.textureCompression=TextureImporterCompression.CompressedHQ;var settings=importer.GetPlatformTextureSettings("Standalone");settings.overridden=true;settings.maxTextureSize=size;settings.format=name=="Normal"?TextureImporterFormat.BC5:TextureImporterFormat.BC7;settings.compressionQuality=100;importer.SetPlatformTextureSettings(settings);importer.SaveAndReimport();}
 foreach(string guid in AssetDatabase.FindAssets("t:Material",new[]{Native})){var mat=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));if(!mat.HasProperty("_Albedo"))continue;var reference=AssetDatabase.LoadAssetAtPath<Material>("Assets/NativeReferences/Moe/Material/HD_Moe.mat");foreach(string property in new[]{"_TransAmbient","_TransDirect","_TransNormalDistortion","_TransScattering","_TransShadow","_Translucency"})mat.SetFloat(property,SavedFloat(reference,property));EditorUtility.SetDirty(mat);if(mat.name.Contains("Eye"))continue;string tier=mat.name.Contains("_Normal_")?"Normal":mat.name.Contains("_Feral_")?"Feral":"Special";mat.SetTexture("_Albedo",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Albedo"+(tier=="Feral"?"_Feral":"")+".png"));mat.SetTexture("_Normal",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_Normal.png"));mat.SetTexture("_RMOE",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Atlas_RMOE_"+tier+".png"));EditorUtility.SetDirty(mat);}AssetDatabase.SaveAssets();BlenderCandidates();});}
 public static void HairInputs(){Guard(()=>{foreach(int angle in new[]{0,90,180,270}){var go=Model();go.transform.rotation=Quaternion.Euler(0,angle,0);var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");r.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Original_LOD0.asset");RenderFaceInputForHair(go,angle);UnityEngine.Object.DestroyImmediate(go);}});}
 static void RenderFaceInputForHair(GameObject model,int angle){foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var old=r.sharedMaterial;var mat=new Material(Shader.Find("Unlit/Texture"));mat.mainTexture=old.HasProperty("_Albedo")?old.GetTexture("_Albedo"):old.HasProperty("_MainTex")?old.GetTexture("_MainTex"):null;r.sharedMaterial=mat;}Render(model,"Hair_Input_"+angle,0,true,true);}
 public static void BlenderCandidates(){Guard(()=>{foreach(int target in new[]{20000,9500,3000}){using(var reader=new BinaryReader(File.OpenRead(Out+"/blender-"+target+".bin"))){int nv=reader.ReadInt32(),nt=reader.ReadInt32();var v=new Vector3[nv];var n=new Vector3[nv];var uv=new Vector2[nv];var bw=new BoneWeight[nv];for(int i=0;i<nv;i++){v[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());n[i]=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle());uv[i]=new Vector2(reader.ReadSingle(),reader.ReadSingle());bw[i]=new BoneWeight{boneIndex0=reader.ReadInt32(),boneIndex1=reader.ReadInt32(),boneIndex2=reader.ReadInt32(),boneIndex3=reader.ReadInt32(),weight0=reader.ReadSingle(),weight1=reader.ReadSingle(),weight2=reader.ReadSingle(),weight3=reader.ReadSingle()};}var tri=new int[nt];for(int i=0;i<nt;i++)tri[i]=reader.ReadInt32();var m=new Mesh{name="RebirthNurse_Blender_"+target,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=v,normals=n,uv=uv,boneWeights=bw,bindposes=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Original_LOD0.asset").bindposes,triangles=tri};m.RecalculateTangents();m.RecalculateBounds();string path=Folder+"/Blender_"+target+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(m,path);else{old.Clear();old.indexFormat=m.indexFormat;old.vertices=m.vertices;old.normals=m.normals;old.tangents=m.tangents;old.uv=m.uv;old.boneWeights=m.boneWeights;old.bindposes=m.bindposes;old.triangles=m.triangles;old.bounds=m.bounds;EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(m);m=old;}var go=Model();go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0").sharedMesh=m;Render(go,"Blender_"+target,0,false);Render(go,"Blender_Face_"+target,0,true);UnityEngine.Object.DestroyImmediate(go);}}});}
 public static void ExportSource(){Guard(()=>{var go=Model();var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var m=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Original_LOD0.asset");var v=m.vertices;var n=m.normals;var uv=m.uv;var bw=m.boneWeights;using(var writer=new BinaryWriter(File.Create(Out+"/source-mesh.bin"))){writer.Write(v.Length);writer.Write(m.triangles.Length);for(int i=0;i<v.Length;i++){var p=r.transform.TransformPoint(v[i]);foreach(float f in new[]{v[i].x,v[i].y,v[i].z,n[i].x,n[i].y,n[i].z,uv[i].x,uv[i].y,p.x,p.y,p.z})writer.Write(f);var w=bw[i];foreach(int id in new[]{w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3})writer.Write(id);foreach(float f in new[]{w.weight0,w.weight1,w.weight2,w.weight3})writer.Write(f);}foreach(int id in m.triangles)writer.Write(id);}File.WriteAllLines(Out+"/bone-names.txt",r.bones.Select(t=>t.name));});}


 static float SavedFloat(Material material,string name){var values=new SerializedObject(material).FindProperty("m_SavedProperties.m_Floats");for(int i=0;i<values.arraySize;i++){var item=values.GetArrayElementAtIndex(i);if(item.FindPropertyRelative("first").stringValue==name)return item.FindPropertyRelative("second").floatValue;}throw new Exception("Native serialized material value missing: "+name);}
 public static void Render(GameObject model,string label,int lod,bool face,bool unlit=false){
  foreach(var temp in UnityEngine.Object.FindObjectsOfType<GameObject>().Where(g=>g.name=="__Skin"||g.name=="Camera"||g.name=="Key"||g.name=="Fill").ToArray())UnityEngine.Object.DestroyImmediate(temp);if(!unlit)RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(model);if(model.name.Contains("Moe"))foreach(var renderer in model.GetComponentsInChildren<SkinnedMeshRenderer>(true))foreach(var material in renderer.sharedMaterials)if(material.name.Contains("MoeHair"))material.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get("Game/Autodesk");if(label.Contains("NoNormal"))foreach(var renderer in model.GetComponentsInChildren<SkinnedMeshRenderer>(true))if(renderer.sharedMaterial.HasProperty("_Normal"))renderer.sharedMaterial.SetTexture("_Normal",null);
  foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true)){if(r.enabled&&r.gameObject.activeInHierarchy&&(!r.name.StartsWith("LOD")||r.name=="LOD"+lod)){var g=new GameObject("__Skin");g.AddComponent<MeshFilter>().sharedMesh=NurseAnatomyRender.WorldSkin(r);g.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials.Take(r.sharedMesh.subMeshCount).ToArray();}r.forceRenderingOff=true;}
  bool hair=label.Contains("Hair_");var c=new GameObject("Camera").AddComponent<Camera>();c.orthographic=true;c.orthographicSize=hair?.31f:face?.155f:1.02f;c.aspect=1;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.13f,.16f,.19f);var centre=hair?new Vector3(0,1.53f,0):face?new Vector3(0,1.64f,.02f):new Vector3(0,.91f,0);if(label.Contains("Feet_")){c.orthographicSize=.27f;centre=new Vector3(0,.20f,0);}if(label.Contains("Tears_")){c.orthographicSize=.48f;centre=new Vector3(0,.83f,0);}if(label.Contains("MoeFace")){c.orthographicSize=.18f;centre=new Vector3(0,1.72f,0);}if(label.EndsWith("_Eyes")){c.orthographicSize=.07f;centre=new Vector3(0,label.StartsWith("Moe")?1.71666f:1.628f,.02f);}c.transform.position=centre+Vector3.forward*3;c.transform.LookAt(centre);c.nearClipPlane=.01f;
  var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.1f;key.transform.rotation=Quaternion.Euler(35,145,0);var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.65f;fill.transform.rotation=Quaternion.Euler(15,-35,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.48f,.48f,.48f);
  var rt=new RenderTexture(1024,1024,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var pixels=new Texture2D(1024,1024,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1024,1024),0,0);pixels.Apply();File.WriteAllBytes(Out+"/"+label+".png",pixels.EncodeToPNG());RenderTexture.active=null;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pixels);
 }
}










